select id, product_name, price, cost, stock_qty, tags, ntile(10) over w_grp as price_bucket, sum(price) over (partition by brand order by price, id rows between unbounded preceding and current row) as running_price, lag(price, 1) over (partition by category order by stock_qty, id) as prev_price, avg(stock_qty) over (partition by category, supplier_id order by stock_qty, id rows between 3 preceding and current row) as stock_qty_avg_3 from products window w_grp as (partition by category order by price desc, id);
